     1	import { at, dateOf, LocalDateTime, previousDate, timeOf } from "../time/localTime";
     2	
     3	/**
     4	 * 야간 방해 금지 — [start, end) 구간(자정을 넘는다)에 걸린 알림은
     5	 * 늦게 보내지 않고 직전 저녁(fallback 시각)으로 당긴다. 금융 알림은 늦으면 안 되기 때문이다.
     6	 */
     7	export class QuietHours {
     8	  constructor(
     9	    private readonly start: string,
    10	    private readonly end: string,
    11	    private readonly fallback: string,
    12	  ) {}
    13	
    14	  contains(t: LocalDateTime): boolean {
    15	    const hm = timeOf(t);
    16	    return this.start > this.end ? hm >= this.start || hm < this.end : hm >= this.start && hm < this.end;
    17	  }
    18	
    19	  /** 구간 밖이면 그대로, 안이면 직전 저녁 fallback 시각 */
    20	  pullBack(t: LocalDateTime): LocalDateTime {
    21	    if (!this.contains(t)) return t;
    22	    const d = dateOf(t);
    23	    const eveningOf = timeOf(t) >= this.start ? d : previousDate(d);
    24	    return at(eveningOf, this.fallback);
    25	  }
    26	}
